244		eventsBefore := len(chart.AuditEvents)
245		// 基于过期版本号更正：拒绝且保持现状，不产生事件。
246		if _, err := s.CorrectRecord(doc, r.ID, 1, "抢占更正", "并发"); !errors.Is(err, ErrConflict) {
247			t.Fatalf("stale correction err = %v, want ErrConflict", err)
248		}
