332		// 再撤回限定授权：没有有效授权，明确拒绝，不泄露记录标识或数量。
333		if err := f.s.Revoke(doc, f.pid, limited.ID); err != nil {
334			t.Fatal(err)
335		}
336		if res, err := f.s.Read(rcv, f.pid, f.e1, Diagnosis); !errors.Is(err, ErrAccessDenied) || len(res.Records) != 0 {
337			t.Fatalf("after all revoke: res=%+v err=%v", res, err)
338		}
339	}
340	
341	// ---- Read：两条限定授权取合集，每条只出现一次；时间窗独立 ----
342	
343	func TestReadUnionOfSelectiveGrantsAndTimeWindow(t *testing.T) {
344		f := setupSelective(t)
345	
346		if _, err := f.s.GrantSelective(doc, f.pid, rcv.ID, nil,
347			[]RecordSelection{sel(f.e1, Diagnosis, f.r1)}, f.start, f.end); err != nil {
348			t.Fatal(err)
349		}
350		if _, err := f.s.GrantSelective(doc, f.pid, rcv.ID, nil,
351			[]RecordSelection{
352				sel(f.e1, Diagnosis, f.r1), // 与上一条重叠
353				sel(f.e1, Diagnosis, f.r2),
354			}, f.start, f.end); err != nil {
355			t.Fatal(err)
356		}
357		res, _ := f.s.Read(rcv, f.pid, f.e1, Diagnosis)
358		ids := readRecordIDs(res)
359		if len(res.Records) != 2 || !ids[f.r1] || !ids[f.r2] {
360			t.Fatalf("union read = %+v", res.Records)
361		}
362		for i := 1; i < len(res.Records); i++ {
363			if res.Records[i-1].RecordID > res.Records[i].RecordID {
364				t.Fatalf("union not in stable id order: %+v", res.Records)
365			}
366		}
367	
368		// 未来才开始的限定授权不参与合并。
369		future, err := f.s.GrantSelective(doc, f.pid, rcvB.ID, nil,
370			[]RecordSelection{sel(f.e1, Diagnosis, f.r1)},
371			f.clk.t.Add(time.Hour), f.clk.t.Add(2*time.Hour))
372		if err != nil {
373			t.Fatal(err)
374		}
375		if _, err := f.s.Read(rcvB, f.pid, f.e1, Diagnosis); !errors.Is(err, ErrAccessDenied) {
376			t.Fatalf("future grant err = %v", err)
377		}
378		// 到窗口内：只看到选中的 r1。
379		f.clk.t = f.clk.t.Add(90 * time.Minute)
380		res, err = f.s.Read(rcvB, f.pid, f.e1, Diagnosis)
381		if err != nil || len(res.Records) != 1 || res.Records[0].RecordID != f.r1 {
382			t.Fatalf("future grant now active: %+v %v", res, err)
383		}
384		// 到期后又拒绝。
385		_ = future
386		f.clk.t = f.end.Add(time.Hour)
387		if _, err := f.s.Read(rcv, f.pid, f.e1, Diagnosis); !errors.Is(err, ErrAccessDenied) {
388			t.Fatalf("expired grants err = %v", err)
389		}
390	}
391	
392	// ---- 交换：每条记录必须被绑定的那一条授权自身覆盖 ----
393	
394	func TestCreateExchangeBoundToSelectiveAuthorization(t *testing.T) {
395		f := setupSelective(t)
396	
397		// 绑定授权只选定 r1。
398		bound, err := f.s.GrantSelective(doc, f.pid, rcv.ID, nil,
399			[]RecordSelection{sel(f.e1, Diagnosis, f.r1)}, f.start, f.end)
400		if err != nil {
401			t.Fatal(err)
402		}
403		// 同一接收方的另一条整类授权覆盖整个 e1 诊断（含 r2），但不能补足绑定授权。
404		if _, err := f.s.Grant(doc, f.pid, rcv.ID,
405			[]Scope{{EncounterID: f.e1, Category: Diagnosis}}, f.start, f.end); err != nil {
406			t.Fatal(err)
407		}
408	
409		// 选中记录打包成功并固化创建时版本。
410		x, err := f.s.CreateExchange(doc, f.pid, rcv.ID, bound.ID, []ID{f.r1}, "req-sel-1")
411		if err != nil {
412			t.Fatalf("create with selected record: %v", err)
413		}
414		if len(x.Package.Records) != 1 || x.Package.Records[0].VersionID != f.r1v1.ID {
415			t.Fatalf("package wrong: %+v", x.Package.Records)
416		}
417	
418		// 更正后包不变。
419		v2, err := f.s.CorrectRecord(doc, f.r1, 1, "诊断1-v2", "更正")
420		if err != nil {
421			t.Fatal(err)
422		}
423		retry, err := f.s.CreateExchange(doc, f.pid, rcv.ID, bound.ID, []ID{f.r1}, "req-sel-1")
424		if err != nil {
425			t.Fatal(err)
426		}
427		if retry.ID != x.ID || retry.Package.Records[0].VersionID != f.r1v1.ID {
428			t.Fatalf("retry refroze package: %+v", retry.Package.Records)
429		}
430		_ = v2
431	
432		// 夹带一条只有其他授权覆盖的 r2：整包拒绝，不留交换或审计，也不占用请求号。
433		auditBefore := len(mustAudit(t, f.s, f.pid))
434		if _, err := f.s.CreateExchange(doc, f.pid, rcv.ID, bound.ID,
435			[]ID{f.r1, f.r2}, "req-sel-2"); !errors.Is(err, ErrAccessDenied) {
436			t.Fatalf("mixed set err = %v, want ErrAccessDenied", err)
437		}
438		if _, err := f.s.CreateExchange(doc, f.pid, rcv.ID, bound.ID,
439			[]ID{f.r2}, "req-sel-2"); !errors.Is(err, ErrAccessDenied) {
440			t.Fatalf("uncovered record err = %v, want ErrAccessDenied", err)
441		}
442		if got := len(mustAudit(t, f.s, f.pid)); got != auditBefore {
443			t.Fatalf("failed exchange added audit: %d -> %d", auditBefore, got)
444		}
445		if xs, _ := f.s.ListExchanges(doc, f.pid); len(xs) != 1 {
446			t.Fatalf("failed exchange persisted: %d", len(xs))
447		}
448		// 请求号未被占用：同请求号改为合法集合应成功。
449		x2, err := f.s.CreateExchange(doc, f.pid, rcv.ID, bound.ID, []ID{f.r1}, "req-sel-2")
450		if err != nil || x2.ID == x.ID {
451			t.Fatalf("request id should not be consumed: x2=%+v err=%v", x2, err)
452		}
453	}
454	
455	// ---- 交换：混合授权中整类与选定记录都可打包 ----
456	
457	func TestCreateExchangeMixedAuthorizationScopes(t *testing.T) {
458		f := setupSelective(t)
459	
460		// 同一条授权：整类覆盖 e1 医嘱，选定 e1 诊断 r1。
461		mixed, err := f.s.GrantSelective(doc, f.pid, rcv.ID,
462			[]Scope{{EncounterID: f.e1, Category: Order}},
463			[]RecordSelection{sel(f.e1, Diagnosis, f.r1)},
464			f.start, f.end)
465		if err != nil {
466			t.Fatal(err)
467		}
468		x, err := f.s.CreateExchange(doc, f.pid, rcv.ID, mixed.ID,
469			[]ID{f.r3, f.r1}, "req-mix")
470		if err != nil {
471			t.Fatalf("mixed exchange: %v", err)
472		}
473		if len(x.Package.Records) != 2 {
474			t.Fatalf("records = %d, want 2", len(x.Package.Records))
475		}
476		// r2 既不在整类范围（医嘱），也未被选定：拒绝。
477		if _, err := f.s.CreateExchange(doc, f.pid, rcv.ID, mixed.ID,
478			[]ID{f.r2}, "req-mix-2"); !errors.Is(err, ErrAccessDenied) {
479			t.Fatalf("uncovered diagnosis err = %v", err)
480		}
481	}
482	
483	// ---- 重开恢复：限定记录、授权状态、历史交换保留 ----
484	
485	func TestSelectivePersistenceAcrossReopen(t *testing.T) {
486		dir := t.TempDir()
487		clk := &fakeClock{t: time.Date(2026, 5, 1, 8, 0, 0, 0, time.UTC)}
488		open := func() *Store {
489			s, err := Open(dir, WithClock(func() time.Time { return clk.t }))
490			if err != nil {
491				t.Fatalf("open: %v", err)
492			}
493			return s
494		}
495	
496		s := open()
497		p, _ := s.RegisterPatient(doc, "限定持久化患者")
498		e, _ := s.AddEncounter(doc, p.ID, time.Time{})
499		d1, _ := s.CreateDraft(doc, p.ID, e.ID, Diagnosis, "诊断1")
500		if _, err := s.ActivateRecord(doc, d1.ID); err != nil {
501			t.Fatal(err)
502		}
503		d2, _ := s.CreateDraft(doc, p.ID, e.ID, Diagnosis, "诊断2")
504		if _, err := s.ActivateRecord(doc, d2.ID); err != nil {
505			t.Fatal(err)
506		}
507		a, _ := s.GrantSelective(doc, p.ID, rcv.ID, nil,
508			[]RecordSelection{sel(e.ID, Diagnosis, d1.ID)},
509			clk.t.Add(-time.Hour), clk.t.Add(48*time.Hour))
510		x, err := s.CreateExchange(doc, p.ID, rcv.ID, a.ID, []ID{d1.ID}, "req-persist-sel")
511		if err != nil {
512			t.Fatal(err)
513		}
514		if err := s.Close(); err != nil {
515			t.Fatal(err)
516		}
517	
518		s2 := open()
519		t.Cleanup(func() { _ = s2.Close() })
520	
521		got, err := s2.GetAuthorization(doc, p.ID, a.ID)
522		if err != nil {
523			t.Fatalf("auth after reopen: %v", err)
524		}
525		if len(got.Scopes) != 0 || len(got.Selections) != 1 || got.Selections[0].RecordID != d1.ID {
526			t.Fatalf("limited scope not preserved: %+v", got)
527		}
528		// 仍只放行选中记录。
529		res, err := s2.Read(rcv, p.ID, e.ID, Diagnosis)
530		if err != nil || len(res.Records) != 1 || res.Records[0].RecordID != d1.ID {
531			t.Fatalf("read after reopen: %+v %v", res, err)
532		}
533		// 历史交换保留，同请求重试返回原交换。
534		retry, err := s2.CreateExchange(doc, p.ID, rcv.ID, a.ID, []ID{d1.ID}, "req-persist-sel")
535		if err != nil || retry.ID != x.ID {
536			t.Fatalf("retry after reopen: id=%q err=%v", retry.ID, err)
537		}
538		// 未选中记录仍不能借该授权打包。
539		if _, err := s2.CreateExchange(doc, p.ID, rcv.ID, a.ID, []ID{d2.ID}, "req-persist-sel-2"); !errors.Is(err, ErrAccessDenied) {
540			t.Fatalf("unselected package after reopen err = %v", err)
541		}
542	}
